    const normalized = name.toLowerCase();
    return (
      normalized.includes("github") &&
      normalized.includes("repo") &&
      (normalized.includes("list") || normalized.includes("user"))
    );
  });

  if (fallback) {
    return fallback;
  }

  throw new Error(
    `Unable to find a GitHub repository listing tool for ${IDENT

